function toMono(interleaved, numCh){
  if(!(numCh>0)) return null;
  var n=Math.floor(interleaved.length/numCh), out=new Array(n);
  for(var i=0;i<n;i++){ var s=0; for(var c=0;c<numCh;c++) s+=interleaved[i*numCh+c]; out[i]=s/numCh; }
  return out;
}
function toStereo(mono){ return mono.reduce(function(a,v){ a.push(v,v); return a; },[]); }
var EXPORTS={toMono:toMono,toStereo:toStereo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StereoMonoForgePure = EXPORTS; }
